import { type RequestEventCommon } from '@builder.io/qwik-city';
import { db } from './db';

export interface UserSession {
  id: number;
  username: string;
  role: 'admin' | 'editor' | 'viewer';
}

export function getCurrentUser(event: RequestEventCommon): UserSession | null {
  const sessionId = event.cookie.get('session')?.value;
  if (!sessionId) return null;

  try {
    const row = db.prepare(`
      SELECT u.id, u.username, u.role
      FROM sessions s
      JOIN users u ON s.userId = u.id
      WHERE s.id = ?
    `).get(sessionId) as any;

    if (!row) return null;
    return {
      id: row.id,
      username: row.username,
      role: row.role,
    };
  } catch (err) {
    return null;
  }
}

export function createSession(userId: number): string {
  const sessionId = crypto.randomUUID();
  db.prepare('INSERT INTO sessions (id, userId) VALUES (?, ?)').run(sessionId, userId);
  return sessionId;
}

export function deleteSession(sessionId: string): void {
  db.prepare('DELETE FROM sessions WHERE id = ?').run(sessionId);
}

import { type RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../db';
import { createSession } from '../../../auth';

export const onPost: RequestHandler = async (event) => {
  try {
    const body = await event.request.json();
    const { username, password } = body || {};

    if (!username || !password) {
      event.status(401);
      return event.json(401, { error: 'Username and password are required' });
    }

    const user = db.prepare('SELECT * FROM users WHERE username = ?').get(username) as any;
    if (!user || user.password !== password) {
      event.status(401);
      return event.json(401, { error: 'Invalid credentials' });
    }

    const sessionId = createSession(user.id);
    event.cookie.set('session', sessionId, {
      path: '/',
      httpOnly: true,
      sameSite: 'lax',
    });

    event.status(200);
    return event.json(200, {
      username: user.username,
      role: user.role,
    });
  } catch (err: any) {
    event.status(401);
    return event.json(401, { error: 'Invalid credentials' });
  }
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { deleteSession } from '../../../auth';

export const onPost: RequestHandler = async (event) => {
  const sessionId = event.cookie.get('session')?.value;
  if (sessionId) {
    deleteSession(sessionId);
  }
  event.cookie.delete('session', { path: '/' });
  event.status(200);
  return event.json(200, { success: true });
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../db';
import { getCurrentUser } from '../../../auth';

export const onGet: RequestHandler = async (event) => {
  const user = getCurrentUser(event);
  if (!user) {
    event.status(401);
    return event.json(401, { error: 'Unauthorized' });
  }

  const content = db.prepare('SELECT id, title, body FROM content').all();
  event.status(200);
  return event.json(200, content);
};

export const onPost: RequestHandler = async (event) => {
  const user = getCurrentUser(event);
  if (!user) {
    event.status(401);
    return event.json(401, { error: 'Unauthorized' });
  }

  if (user.role !== 'admin' && user.role !== 'editor') {
    event.status(403);
    return event.json(403, { error: 'Forbidden' });
  }

  try {
    const body = await event.request.json();
    const { title, body: contentBody } = body || {};

    if (!title || !contentBody) {
      event.status(400);
      return event.json(400, { error: 'Title and body are required' });
    }

    const info = db.prepare('INSERT INTO content (title, body) VALUES (?, ?)').run(title, contentBody);
    const createdId = Number(info.lastInsertRowid);

    event.status(201);
    return event.json(201, {
      id: createdId,
      title,
      body: contentBody,
    });
  } catch (err: any) {
    event.status(400);
    return event.json(400, { error: 'Invalid request' });
  }
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../db';
import { getCurrentUser } from '../../../../auth';

export const onDelete: RequestHandler = async (event) => {
  const user = getCurrentUser(event);
  if (!user) {
    event.status(401);
    return event.json(401, { error: 'Unauthorized' });
  }

  if (user.role !== 'admin' && user.role !== 'editor') {
    event.status(403);
    return event.json(403, { error: 'Forbidden' });
  }

  const id = Number(event.params.id);
  if (isNaN(id)) {
    event.status(400);
    return event.json(400, { error: 'Invalid ID' });
  }

  // Check if content exists
  const existing = db.prepare('SELECT id FROM content WHERE id = ?').get(id);
  if (!existing) {
    event.status(404);
    return event.json(404, { error: 'Not Found' });
  }

  db.prepare('DELETE FROM content WHERE id = ?').run(id);
  event.status(200);
  return event.json(200, { success: true });
};

import { type RequestHandler } from '@builder.io/qwik-city';
import { db } from '../../../../db';
import { getCurrentUser } from '../../../../auth';

export const onGet: RequestHandler = async (event) => {
  const user = getCurrentUser(event);
  if (!user) {
    event.status(401);
    return event.json(401, { error: 'Unauthorized' });
  }

  if (user.role !== 'admin') {
    event.status(403);
    return event.json(403, { error: 'Forbidden' });
  }

  const users = db.prepare('SELECT id, username, role FROM users').all();
  event.status(200);
  return event.json(200, users);
};

export const onPost: RequestHandler = async (event) => {
  const user = getCurrentUser(event);
  if (!user) {
    event.status(401);
    return event.json(401, { error: 'Unauthorized' });
  }

  if (user.role !== 'admin') {
    event.status(403);
    return event.json(403, { error: 'Forbidden' });
  }

  try {
    const body = await event.request.json();
    const { username, password, role } = body || {};

    if (!username || !password || !role) {
      event.status(400);
      return event.json(400, { error: 'Username, password and role are required' });
    }

    if (role !== 'admin' && role !== 'editor' && role !== 'viewer') {
      event.status(400);
      return event.json(400, { error: 'Role must be admin, editor, or viewer' });
    }

    // Check if username already exists
    const existing = db.prepare('SELECT id FROM users WHERE username = ?').get(username);
    if (existing) {
      event.status(400);
      return event.json(400, { error: 'Username already exists' });
    }

    const info = db.prepare('INSERT INTO users (username, password, role) VALUES (?, ?, ?)').run(username, password, role);
    const createdId = Number(info.lastInsertRowid);

    event.status(201);
    return event.json(201, {
      id: createdId,
      username,
      role,
    });
  } catch (err: any) {
    event.status(400);
    return event.json(400, { error: 'Invalid request' });
  }
};

